insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sociological-theory', 'Structural functionalism', 'Structural functionalism, or simply functionalism, is "a framework for building theory that sees society as a complex system whose parts work together to promote solidarity and stability". This approach looks at society through a macro-level orientation, which is a broad focus on the social structures that shape society as a whole, and believes that society has evolved like organisms. This approach looks at both social structure and social functions. Functionalism addresses society as a whole in terms of the function of its constituent elements; namely norms, customs, traditions, and institutions. A common analogy called the organic or biological analogy, popularized by Herbert Spencer, presents these parts of society as human body "organs" that work toward the proper functioning of the "body" as a whole. In the most basic terms, it simply emphasizes "the effort to impute, as rigorously as possible, to each feature, custom, or practice, its effect on the functioning of a supposedly stable, cohesive system". For Talcott Parsons, "structural-functionalism" came to describe a particular stage in the methodological development of social science, rather than a specific school of thought.', 'Wikipedia: Structural functionalism', 'https://en.wikipedia.org/w/index.php?title=Structural_functionalism&oldid=1379034534', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
