insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sociological-theory', 'Social constructionism: Educational psychology', 'Like social constructionism, social constructivism states that people work together to construct artifacts. While social constructionism focuses on the artifacts that are created through the social interactions of a group, social constructivism focuses on an individual''s learning that takes place because of his or her interactions in a group. Social constructivism has been studied by many educational psychologists, who are concerned with its implications for teaching and learning. For more on the psychological dimensions of social constructivism, see the work of Lev Vygotsky, Ernst von Glasersfeld and A. Sullivan Palincsar.', 'Wikipedia: Social constructionism', 'https://en.wikipedia.org/w/index.php?title=Social_constructionism&oldid=1374272434', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
