insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sociological-theory', 'Manifest and latent functions and dysfunctions', 'Manifest and latent functions are social scientific concepts created by anthropologist Bronisław Malinowski in 1922 while studying the Trobriand Islanders in the Western Pacific. It was later modified for sociology by Robert K. Merton. Merton appeared interested in sharpening the conceptual tools to be employed in a functional analysis. Each system in society has a specific function that relies on and is associated to other systems. When these systems function, it leads to social stability. Dysfunction in one or more systems leads to social instability. Both functions and dysfunctions can be latent or manifest. Manifest functions or dysfunctions are deliberate and known. While latent functions or dysfunctions are unintended and/or go unrecognized by many. Positive or negative values are not attached to functions or dysfunctions. In other words, things that are often viewed by people as wrong or harmful can lead to social stability as much as things that are commonly viewed as right or fair. the distinction between manifest and latent functions was devised to preclude... confusion... between conscious motivations for social behaviour and its objective consequences Merton noted that he has "... adapted the terms "manifest" and "latent" from their use in another context by Freud...".', 'Wikipedia: Manifest and latent functions and dysfunctions', 'https://en.wikipedia.org/w/index.php?title=Manifest_and_latent_functions_and_dysfunctions&oldid=1379781497', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sociological-theory' and body = 'Manifest and latent functions are social scientific concepts created by anthropologist Bronisław Malinowski in 1922 while studying the Trobriand Islanders in the Western Pacific. It was later modified for sociology by Robert K. Merton. Merton appeared interested in sharpening the conceptual tools to be employed in a functional analysis. Each system in society has a specific function that relies on and is associated to other systems. When these systems function, it leads to social stability. Dysfunction in one or more systems leads to social instability. Both functions and dysfunctions can be latent or manifest. Manifest functions or dysfunctions are deliberate and known. While latent functions or dysfunctions are unintended and/or go unrecognized by many. Positive or negative values are not attached to functions or dysfunctions. In other words, things that are often viewed by people as wrong or harmful can lead to social stability as much as things that are commonly viewed as right or fair. the distinction between manifest and latent functions was devised to preclude... confusion... between conscious motivations for social behaviour and its objective consequences Merton noted that he has "... adapted the terms "manifest" and "latent" from their use in another context by Freud...".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sociological-theory', 'Manifest and latent functions and dysfunctions: Functions', 'Manifest functions are the consequences that people see, observe or even expect. It is explicitly stated and understood by the participants in the relevant action. The manifest function of a rain dance, according to Merton in his 1957 Social Theory and Social Structure, is to produce rain, and this outcome is intended and desired by people participating in the ritual. Latent functions are those that are neither recognized nor intended. A latent function of a behavior is not explicitly stated, recognized, or intended by the people involved. Thus, they are identified by observers. In the example of rain ceremony, the latent function reinforces the group identity by providing a regular opportunity for the members of a group to meet and engage in a common activity. Peter L. Berger describes a series of examples illustrating the differences between manifest functions and latent dysfunctions:', 'Wikipedia: Manifest and latent functions and dysfunctions', 'https://en.wikipedia.org/w/index.php?title=Manifest_and_latent_functions_and_dysfunctions&oldid=1379781497', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
