insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sociological-theory', 'Manifest and latent functions and dysfunctions: Functions', '"...the “manifest” function of antigambling legislation may be to suppress gambling, its “latent” function to create an illegal empire for the gambling syndicates. Or Christian missions in parts of Africa “manifestly” tried to convert Africans to Christianity, “latently” helped to destroy the indigenous tribal cultures and this provided an important impetus towards rapid social transformation. Or the control of the Communist Party over all sectors of social life in Russia “manifestly” was to assure the continued dominance of the revolutionary ethos, “latently” created a new class of comfortable bureaucrats uncannily bourgeois in its aspirations and increasingly disinclined toward the self-denial of Bolshevik dedication (nomenklatura). Or the “manifest” function of many voluntary associations in America is sociability and public service, the “latent” function to attach status indices to those permitted to belong to such associations.” " While Talcott Parsons tends to emphasize the manifest functions of social behavior, Merton sees attention to latent functions as increasing the understanding of society: the distinction between manifest and latent forces the sociologist to go beyond the reasons individuals give for their actions or for the existence of customs and institutions; it makes them look for other social consequences that allow these practices’ survival and illuminate the way society works.', 'Wikipedia: Manifest and latent functions and dysfunctions', 'https://en.wikipedia.org/w/index.php?title=Manifest_and_latent_functions_and_dysfunctions&oldid=1379781497', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sociological-theory' and body = '"...the “manifest” function of antigambling legislation may be to suppress gambling, its “latent” function to create an illegal empire for the gambling syndicates. Or Christian missions in parts of Africa “manifestly” tried to convert Africans to Christianity, “latently” helped to destroy the indigenous tribal cultures and this provided an important impetus towards rapid social transformation. Or the control of the Communist Party over all sectors of social life in Russia “manifestly” was to assure the continued dominance of the revolutionary ethos, “latently” created a new class of comfortable bureaucrats uncannily bourgeois in its aspirations and increasingly disinclined toward the self-denial of Bolshevik dedication (nomenklatura). Or the “manifest” function of many voluntary associations in America is sociability and public service, the “latent” function to attach status indices to those permitted to belong to such associations.” " While Talcott Parsons tends to emphasize the manifest functions of social behavior, Merton sees attention to latent functions as increasing the understanding of society: the distinction between manifest and latent forces the sociologist to go beyond the reasons individuals give for their actions or for the existence of customs and institutions; it makes them look for other social consequences that allow these practices’ survival and illuminate the way society works.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sociological-theory', 'Manifest and latent functions and dysfunctions: Dysfunctions', 'Dysfunctions can also be manifest or latent. While functions are intended or recognized (manifest), and may have a positive effect on society, dysfunctions are unintended or unrecognized, and have a negative effect on society. Manifest dysfunctions are anticipated disruptions of social life. For example, a manifest dysfunction of a festival might include disruptions of transportation and excessive production of garbage. Latent dysfunctions are unintended and unanticipated disruptions of order and stability. In the festival example, they would be represented by people missing work due to the traffic jam.', 'Wikipedia: Manifest and latent functions and dysfunctions', 'https://en.wikipedia.org/w/index.php?title=Manifest_and_latent_functions_and_dysfunctions&oldid=1379781497', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
